SELECT


WHERE s.is_deleted = 0 AND s.product_id = #{productId}
ORDER BY s.sort ASC, s.id ASC

SELECT



    s.is_deleted = 0

        AND (p.product_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.product_code LIKE CONCAT('%', #{q.keyword}, '%')
        OR s.sku_code LIKE CONCAT('%', #{q.keyword}, '%')
        OR s.spec_text LIKE CONCAT('%', #{q.keyword}, '%'))


        AND s.product_id = #{q.productId}


        AND p.category_id = #{q.categoryId}


        AND p.store_id = #{q.storeId}



        AND p.section_id = #{q.sectionId}



        AND s.sale_enable = #{q.saleEnable}


        AND p.status = #{q.productStatus}



        AND p.user_id = #{q.currentUserId}



ORDER BY s.sale_enable DESC, s.product_id DESC, s.sort ASC, s.id ASC

